planPhases.notes:
In src/benchmark-frontend/src/components/ProtectedRoute.tsx, the component currently ignores any JSX children and always renders <Outlet /> when authenticated. The protectedRoute.test.tsx test wraps content as children (<ProtectedRoute><div data-testid="protected-content">Protected</div></ProtectedRoute>) and expects that content to render.

Fix: accept an optional children prop and render children ?? <Outlet /> when authenticated:

import { Navigate, Outlet } from 'react-router-dom';
import { useAuthContext } from '../context/AuthContext';
import type { ReactNode } from 'react';

type Props = { children?: ReactNode };

export default function ProtectedRoute({ children }: Props) {
  const { user } = useAuthContext();
  return user ? (children ?? <Outlet />) : <Navigate to="/login" replace />;
}

This preserves the existing App.tsx usage (<Route element={<ProtectedRoute />}> with no children uses <Outlet />) while also making the test pass.
